PRAGMA foreign_keys=ON;
CREATE TABLE workspace(id TEXT PRIMARY KEY, contract TEXT NOT NULL CHECK(contract='brenda'), schema_digest TEXT NOT NULL, repository TEXT NOT NULL, github TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP, modified_at TEXT);
CREATE TABLE findings(id TEXT PRIMARY KEY, title TEXT NOT NULL, quotation TEXT NOT NULL, reason TEXT NOT NULL DEFAULT '', proposed TEXT NOT NULL DEFAULT '', path TEXT NOT NULL, page_url TEXT NOT NULL, target TEXT CHECK(target IN ('main','develop')), severity TEXT NOT NULL CHECK(severity IN ('high','medium','low')), evidence TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','rejected')), created_at TEXT DEFAULT CURRENT_TIMESTAMP, modified_at TEXT);
CREATE TABLE coverage(path TEXT PRIMARY KEY, basis TEXT NOT NULL, notes TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP, modified_at TEXT);
CREATE TABLE batches(id INTEGER PRIMARY KEY, title TEXT NOT NULL, target TEXT NOT NULL CHECK(target IN ('main','develop')), branch TEXT, worktree TEXT, base_sha TEXT, submitted_at TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, modified_at TEXT);
CREATE TABLE batch_findings(batch_id INTEGER NOT NULL REFERENCES batches(id), finding_id TEXT NOT NULL REFERENCES findings(id), instructions TEXT NOT NULL DEFAULT '', created_at TEXT DEFAULT CURRENT_TIMESTAMP, modified_at TEXT, PRIMARY KEY(batch_id,finding_id));
CREATE TABLE pull_requests(id INTEGER PRIMARY KEY, batch_id INTEGER NOT NULL REFERENCES batches(id), url TEXT NOT NULL, metadata TEXT, tree TEXT, patches TEXT, observed_at TEXT, sync_error TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, modified_at TEXT, UNIQUE(batch_id,url));
CREATE TABLE handoffs(id INTEGER PRIMARY KEY, batch_id INTEGER REFERENCES batches(id), kind TEXT NOT NULL CHECK(kind IN ('discovery','implementation','validation','follow_up')), prompt TEXT NOT NULL DEFAULT '', session_url TEXT, received_at TEXT, dismissed_at TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP, modified_at TEXT);
CREATE TABLE handoff_findings(handoff_id INTEGER NOT NULL REFERENCES handoffs(id), finding_id TEXT NOT NULL REFERENCES findings(id), PRIMARY KEY(handoff_id,finding_id));
CREATE TABLE discovery_prompts(id INTEGER PRIMARY KEY, handoff_id INTEGER NOT NULL UNIQUE REFERENCES handoffs(id), prompt TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP, modified_at TEXT);
CREATE TABLE checks(id INTEGER PRIMARY KEY, batch_id INTEGER NOT NULL, finding_id TEXT NOT NULL, handoff_id INTEGER REFERENCES handoffs(id), pr_id INTEGER NOT NULL REFERENCES pull_requests(id), revision TEXT NOT NULL, source_blobs TEXT NOT NULL, proposed TEXT NOT NULL, outcome TEXT NOT NULL CHECK(outcome IN ('pass','needs_work','blocked')), recommendation TEXT NOT NULL CHECK(recommendation IN ('accept','needs_work','revert')), summary TEXT NOT NULL, target_url TEXT NOT NULL DEFAULT '', reporter TEXT NOT NULL, created_at TEXT NOT NULL, modified_at TEXT, FOREIGN KEY(batch_id,finding_id) REFERENCES batch_findings(batch_id,finding_id));
CREATE INDEX check_history ON checks(batch_id,finding_id,id);
CREATE TABLE evidence(id INTEGER PRIMARY KEY, check_id INTEGER NOT NULL REFERENCES checks(id), label TEXT NOT NULL, mime_type TEXT NOT NULL CHECK(mime_type IN ('image/png','image/jpeg','image/webp')), content BLOB NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP, modified_at TEXT);
CREATE TABLE decisions(id INTEGER PRIMARY KEY, batch_id INTEGER NOT NULL, finding_id TEXT NOT NULL, check_id INTEGER REFERENCES checks(id), action TEXT NOT NULL CHECK(action IN ('accept','needs_work','revert','deferred','withdrawn','resolved_by_revert','clear')), notes TEXT NOT NULL DEFAULT '', observed_heads TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(batch_id,finding_id) REFERENCES batch_findings(batch_id,finding_id));
CREATE INDEX decision_history ON decisions(batch_id,finding_id,id);
CREATE TABLE publication_authorizations(id INTEGER PRIMARY KEY, batch_id INTEGER NOT NULL REFERENCES batches(id), observed_heads TEXT NOT NULL, decisions TEXT NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
